==== ValidateOwnerFields ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import jakarta.validation.ConstraintViolation;
import jakarta.validation.Validator;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.samples.petclinic.rest.function.common.Postcodes;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Rejects a body that is missing (absent) or blank
 * (whitespace only) in any of firstName, lastName, address, city or telephone — {@code @Size(min = 1)}
 * on the DTO does not catch a whitespace-only value, so the check is explicit here. The remaining
 * schema constraints (pattern, max length) are validated too, so a bad value is still a 400.
 *
 * <p>Binds the body directly (no {@code @Valid}) so that a missing field surfaces as this rule's
 * {@code errors} response rather than the generic schema-validation escalation, and publishes the
 * body for {@link BuildOwner} to consume.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Validator validator, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        List<String> errors = new ArrayList<>();
        normalizeAddress(request);
        addIfBlank(errors, "firstName", request.getFirstName());
        addIfBlank(errors, "lastName", request.getLastName());
        addIfBlank(errors, "address", request.getAddress());
        addIfBlank(errors, "city", request.getCity());
        normalizeTelephone(errors, request);
        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
            String field = violation.getPropertyPath().toString();
            if (!field.isEmpty() && !errors.contains(field)) {
                errors.add(field);
            }
        }
        validatePostcode(errors, request);
        if (!errors.isEmpty()) {
            throw new MissingOwnerFieldsException(errors);
        }
        normalizeEmail(request);
        validated.set(request);
    }

    /**
     * Email is optional. When absent nothing is done; when present the schema {@code @Email}
     * constraint (checked above) has already rejected a syntactically invalid address with a
     * {@code 400}, so a value reaching here is valid and is stored and returned lower-cased.
     */
    private static void normalizeEmail(OwnerFieldsDto request) {
        String email = request.getEmail();
        if (email != null) {
            request.setEmail(email.toLowerCase(java.util.Locale.ROOT));
        }
    }

    /**
     * Canonically normalize the address (trim, collapse whitespace, upper-case, expand common
     * abbreviations) and write it back onto the request so it is stored and returned in normalized
     * form. Running before the blank check means an address that is whitespace-only — and so blank
     * after normalization — is rejected as an {@code address} required-field error (400).
     */
    private static void normalizeAddress(OwnerFieldsDto request) {
        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
    }

    /**
     * Postcode is optional and validated only when present. Its 4-digit format is enforced by the
     * schema {@code @Pattern} (checked above, so a malformed value is already a {@code postcode}
     * error). When it is well-formed it must also be in range for the region derived from the
     * owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region
     * accepts any 4-digit postcode. An out-of-range postcode is a {@code postcode} error (400).
     */
    private static void validatePostcode(List<String> errors, OwnerFieldsDto request) {
        String postcode = request.getPostcode();
        if (postcode != null && !errors.contains("postcode")
                && !Postcodes.isValidForCity(postcode, request.getCity())) {
            errors.add("postcode");
        }
    }

    private static void addIfBlank(List<String> errors, String name, String value) {
        if (value == null || value.isBlank()) {
            errors.add(name);
        }
    }

    /**
     * Normalize the telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
     * '+' with country code is kept as-is; otherwise the number is assumed to be Australian ('+61')
     * and a single leading '0' is dropped from the national digits. The result must have 8 to 15
     * digits after the '+'. The E.164 value is written back onto the request so it is stored and
     * returned as {@code telephone}. Anything that cannot form a valid E.164 number is a
     * {@code telephone} error (400).
     */
    private static void normalizeTelephone(List<String> errors, OwnerFieldsDto request) {
        String e164 = toE164(request.getTelephone());
        if (e164 == null) {
            errors.add("telephone");
            return;
        }
        request.setTelephone(e164);
    }

    /**
     * Country codes with a fixed national-number length. When a number's country code appears here
     * its national digits (everything after the code) must match exactly, otherwise it is rejected;
     * country codes not listed fall back to the generic 8–15 total-digit rule. '+61' (Australia)
     * requires 9 national digits, '+1' (NANP) requires 10.
     */
    private static final java.util.Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY =
            java.util.Map.of("61", 9, "1", 10);

    /**
     * Convert a raw telephone into E.164 form, or return {@code null} when it cannot form a valid
     * E.164 number (fewer than 8 or more than 15 digits after the '+', a national-number length that
     * is wrong for its country code, or stray non-digit characters remaining after the allowed
     * separators are stripped).
     */
    static String toE164(String value) {
        if (value == null) {
            return null;
        }
        String cleaned = value.replaceAll("[\\s()-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return null;
        }
        if (!hasValidNationalLength(digits)) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * For a country code with a fixed national-number length, check the national digits (everything
     * after the code) match that length exactly. Unknown country codes pass (already bounded by the
     * generic 8–15 total-digit rule).
     */
    private static boolean hasValidNationalLength(String digits) {
        for (java.util.Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
            String code = entry.getKey();
            if (digits.startsWith(code)) {
                return digits.length() - code.length() == entry.getValue();
            }
        }
        return true;
    }
}

==== RejectDisposableEmailDomain ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;

/**
 * Step of {@code POST /api/owners} that runs after {@link ValidateOwnerFields} has published the
 * request (with the email already normalized to lower case). Rejects the request when the email's
 * domain is on the disposable-domain blocklist, so a throwaway address is a 400 Bad Request rather
 * than a create. Email is optional; an absent or domain-less value is left for the other rules.
 */
public class RejectDisposableEmailDomain {

    /** Domains for throwaway email providers that are not accepted. */
    static final Set<String> BLOCKED_DOMAINS =
            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
        String email = request.getEmail();
        if (email == null) {
            return;
        }
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return;
        }
        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
        if (BLOCKED_DOMAINS.contains(domain)) {
            throw new DisposableEmailDomainException(domain);
        }
    }
}

==== RejectFutureRegistrationDate ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Step of {@code POST /api/owners} that runs after {@link ValidateOwnerFields} has published the
 * request and before {@link ResolveRegistrationDate}. Rejects the request when the supplied
 * {@code registrationDate} is later than the server's current date, so a future date is a 400 Bad
 * Request rather than being accepted or rolled forward to a business day. A request without a
 * {@code registrationDate} (the date defaults to today) is always allowed.
 */
public class RejectFutureRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied != null && supplied.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(supplied);
        }
    }
}

==== ResolveRegistrationDate ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.function.common.BusinessDay;

/**
 * Step of {@code POST /api/owners} that resolves the effective registration date and adjusts it to a
 * business day. The effective date is the supplied {@code registrationDate} when present, otherwise
 * the server's current date; a Saturday or Sunday is rolled forward to the next Monday.
 *
 * <p>Runs before {@link RejectDailyOwnerLimit} and {@link BuildOwner} and publishes the adjusted
 * date as a {@code LocalDate} variable, so the daily create-limit counts owners per adjusted
 * business day, the new owner is stored with the adjusted date, and any value derived from it (the
 * membership number's year segment) uses the adjusted date too.
 */
public class ResolveRegistrationDate {

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
        LocalDate effective = request.getRegistrationDate() != null
                ? request.getRegistrationDate() : LocalDate.now();
        registrationDate.set(BusinessDay.rollForward(effective));
    }
}

==== RejectDuplicateIdentity ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
import org.springframework.samples.petclinic.rest.function.common.IdentityKeys;

/**
 * The duplicate-detection step of {@code POST /api/owners}. Runs after {@link ValidateOwnerFields}
 * has normalized the telephone and email. It computes the request's deterministic
 * {@code householdId} from its last name and postcode (see {@link Households#householdId}) and
 * rejects the create with a 409 Conflict in two cases:
 *
 * <ul>
 * <li><b>Identity duplicate</b> — the request's whole {@code identityKey}
 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) equals an existing
 * owner's. This always rejects, even when {@code sharesHousehold} is set.</li>
 * <li><b>Household duplicate</b> — an existing owner already occupies the same household (same
 * computed {@code householdId}, i.e. same last name and postcode). This rejects <em>unless</em> the
 * request opts in with {@code sharesHousehold: true}, in which case the owner is created as a
 * declared household member.</li>
 * </ul>
 *
 * <p>{@code sharesHousehold} therefore only bypasses the household-duplicate block; it never lets a
 * full identity duplicate through.
 */
public class RejectDuplicateIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String householdId = Households.householdId(request.getLastName(), request.getPostcode());
        String identityKey = IdentityKeys.of(request.getTelephone(), request.getEmail(), householdId);
        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(IdentityKeys.of(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
            if (!sharesHousehold && householdId.equals(householdIdOf(existing))) {
                throw new DuplicateIdentityException(householdId);
            }
        }
    }

    /** The household an existing owner belongs to, computed from its last name and postcode. */
    private static String householdIdOf(Owner existing) {
        return Households.householdId(existing.getLastName(), existing.getPostcode());
    }
}

==== RejectCityAtCapacity ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that runs after {@link ValidateOwnerFields} has published the
 * request. Rejects the request when the named city already contains {@value #MAX_OWNERS_PER_CITY}
 * or more owners, so a full city is a 409 Conflict rather than an over-capacity create. City
 * matching is case-insensitive.
 */
public class RejectCityAtCapacity {

    /** Maximum number of owners a single city may contain. */
    static final int MAX_OWNERS_PER_CITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        long count = ownerRepository.findAll().stream()
                .map(Owner::getCity)
                .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
                .count();
        if (count >= MAX_OWNERS_PER_CITY) {
            throw new CityAtCapacityException(city);
        }
    }
}

==== RejectDailyOwnerLimit ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that rejects the request when {@value #MAX_OWNERS_PER_DAY} or
 * more owners have already been created for this request's business day, counted by {@link
 * Owner#getRegistrationDate()}, so a full day is a 429 Too Many Requests rather than an over-quota
 * create. The day counted is the adjusted business day resolved by {@link ResolveRegistrationDate}
 * (weekends roll forward to Monday), the same date {@link BuildOwner} will stamp on the new owner,
 * so the count reflects only owners already persisted against that business day.
 */
public class RejectDailyOwnerLimit {

    /** Maximum number of owners that may be created in a single day. */
    static final int MAX_OWNERS_PER_DAY = 100;

    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
            throws DailyOwnerLimitException {
        long count = ownerRepository.findAll().stream()
                .map(Owner::getRegistrationDate)
                .filter(registrationDate::equals)
                .count();
        if (count >= MAX_OWNERS_PER_DAY) {
            throw new DailyOwnerLimitException((int) count);
        }
    }
}

==== BuildOwner ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, @Val LocalDate registrationDate,
            OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date has already been resolved and adjusted to a business day
        // by ResolveRegistrationDate; store that, overriding any supplied (possibly weekend) value.
        owner.setRegistrationDate(registrationDate);
        built.set(owner);
    }
}

