package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Step of {@code POST /api/owners} that runs after {@link BuildOwner} has produced the owner and
 * stamps its {@code householdId}. The id is derived deterministically from the owner's last name and
 * postcode (see {@link Households#householdId}), so every owner with the same last name and postcode
 * gets the same value automatically — the household needs no linking step and there is nothing to
 * back-fill.
 *
 * <p>Unlike the earlier behaviour, this is unconditional: {@code sharesHousehold} no longer creates
 * the household link (it only bypasses the household-duplicate block in {@link RejectDuplicateIdentity})
 * and even a lone owner carries the computed id. Downstream steps that key off the household —
 * {@link AssignHouseholdSize} and duplicate detection — read this same computed value.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(Households.householdId(owner.getLastName(), owner.getPostcode()));
    }
}

==== AssignHouseholdSize ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that records how many owners belong to this owner's household —
 * the owners sharing its {@code householdId} — once this create is accounted for, storing the total
 * on the owner as {@code householdMemberCount}.
 *
 * <p>Runs after {@link AssignHousehold} (which stamps the deterministic {@code householdId} keyed on
 * last name and postcode) and before {@link SaveOwner}, so the count sees the existing members already
 * in the repository plus this owner, which is not yet persisted and so is added explicitly. Every
 * owner now carries a computed {@code householdId}; a lone owner simply has a household of one.
 */
public class AssignHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            // A lone owner has no household id: the household is just this owner.
            owner.setHouseholdMemberCount(1);
            return;
        }
        int members = 1; // this owner, not yet persisted
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(existing.getHouseholdId())) {
                members++;
            }
        }
        owner.setHouseholdMemberCount(members);
    }
}

==== AssignNamesakeCount ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that counts how many existing owners already share this owner's
 * {@code firstName} and {@code lastName} — compared case-insensitively — and stores the total on the
 * owner as {@code namesakeCount}.
 *
 * <p>Runs after {@link BuildOwner} so the owner carries its names, and before {@link SaveOwner} so
 * the count reflects only owners that existed before this create: the new owner is not yet persisted
 * and so is never counted among its own namesakes. {@code @Val} yields the built owner, mutated in
 * place and persisted by the save step.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = normalize(owner.getFirstName());
        String lastName = normalize(owner.getLastName());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equals(normalize(existing.getFirstName()))
                    && lastName.equals(normalize(existing.getLastName()))) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    /** Lower-case for a case-insensitive comparison; a null name normalizes to empty. */
    private static String normalize(String value) {
        return value == null ? "" : value.toLowerCase(Locale.ROOT);
    }
}

==== AssignBulkSignupWarning ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that flags a bulk signup: when more than {@value
 * #BULK_SIGNUP_THRESHOLD} owners have already been created for this request's business day, counted
 * by {@link Owner#getRegistrationDate()}, the new owner is stamped with {@code bulkSignupWarning}
 * true; otherwise false. The day counted is the adjusted business day resolved by {@link
 * ResolveRegistrationDate} (weekends roll forward to Monday), the same date {@link BuildOwner}
 * stamps on the new owner — the same accumulation path as the daily create-limit rule.
 *
 * <p>Runs after {@link BuildOwner} so the owner exists to stamp, and before {@link SaveOwner} so the
 * count reflects only owners already persisted against that business day, never this owner itself.
 * {@code @Val} yields the built owner, mutated in place and persisted by the save step.
 */
public class AssignBulkSignupWarning {

    /** The new owner warns of a bulk signup once more than this many owners share its business day. */
    static final int BULK_SIGNUP_THRESHOLD = 80;

    public void service(@Val Owner owner, @Val LocalDate registrationDate,
            OwnerRepository ownerRepository) {
        long count = ownerRepository.findAll().stream()
                .map(Owner::getRegistrationDate)
                .filter(registrationDate::equals)
                .count();
        owner.setBulkSignupWarning(count > BULK_SIGNUP_THRESHOLD);
    }
}

==== AssignPossibleDuplicate ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Soft-match step of {@code POST /api/owners}. By the time it runs the request has already passed
 * {@link RejectDuplicateIdentity}, so it is <em>not</em> a hard duplicate; this step then looks for a
 * weaker signal that it might be one anyway: an existing owner that shares this owner's
 * {@code lastName} (compared case-insensitively) and {@code postcode} but has a <em>different</em>
 * telephone. Such an owner is still created, but is flagged with {@code possibleDuplicate = true} and
 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest id when several match).
 * When nothing matches, {@code possibleDuplicate} is set to {@code false} and no id is recorded.
 *
 * <p>A <em>declared</em> household member — one created with {@code sharesHousehold: true} — is never
 * flagged: it already reached this step by opting past the household-duplicate block in
 * {@link RejectDuplicateIdentity}, so sharing a same-household owner's lastName and postcode is
 * expected, not a suspected duplicate.
 *
 * <p>Runs after {@link BuildOwner} so the owner carries its normalized lastName, postcode and
 * telephone, and before {@link SaveOwner} so the comparison sees only owners that existed before this
 * create — the new owner is not yet persisted and so never matches itself. {@code @Val} yields the
 * built owner, mutated in place and persisted by the save step.
 */
public class AssignPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            // A declared household member is not a suspected duplicate.
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
            return;
        }
        String lastName = Households.normalizeName(owner.getLastName());
        String postcode = normalizePostcode(owner.getPostcode());
        String telephone = owner.getTelephone();
        Integer match = null;
        if (postcode != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (lastName.equals(Households.normalizeName(existing.getLastName()))
                        && postcode.equals(normalizePostcode(existing.getPostcode()))
                        && !equalsSafely(telephone, existing.getTelephone())
                        && existing.getId() != null
                        && (match == null || existing.getId() < match)) {
                    match = existing.getId();
                }
            }
        }
        owner.setPossibleDuplicate(match != null);
        owner.setPossibleDuplicateOf(match);
    }

    /** Trim the postcode, treating a null or blank value as absent (no possible-duplicate match). */
    private static String normalizePostcode(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }

    private static boolean equalsSafely(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }
}

