4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import jakarta.validation.ConstraintViolation;
8	import jakarta.validation.Validator;
9	import net.officefloor.plugin.variable.Out;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
12	import org.springframework.samples.petclinic.rest.function.common.Postcodes;
13	import org.springframework.web.bind.annotation.RequestBody;
14	
15	/**
16	 * First step of {@code POST /api/owners}. Rejects a body that is missing (absent) or blank
17	 * (whitespace only) in any of firstName, lastName, address, city or telephone — {@code @Size(min = 1)}
18	 * on the DTO does not catch a whitespace-only value, so the check is explicit here. The remaining
19	 * schema constraints (pattern, max length) are validated too, so a bad value is still a 400.
20	 *
21	 * <p>Binds the body directly (no {@code @Valid}) so that a missing field surfaces as this rule's
22	 * {@code errors} response rather than the generic schema-validation escalation, and publishes the
23	 * body for {@link BuildOwner} to consume.
24	 */
25	public class ValidateOwnerFields {
26	
27	    public void service(@RequestBody OwnerFieldsDto request, Validator validator, Out<OwnerFieldsDto> validated)
28	            throws MissingOwnerFieldsException {
29	        List<String> errors = new ArrayList<>();
30	        normalizeAddress(request);
31	        addIfBlank(errors, "firstName", request.getFirstName());
32	        addIfBlank(errors, "lastName", request.getLastName());
33	        addIfBlank(errors, "address", request.getAddress());
34	        addIfBlank(errors, "city", request.getCity());
35	        normalizeTelephone(errors, request);
36	        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
37	            String field = violation.getPropertyPath().toString();
38	            if (!field.isEmpty() && !errors.contains(field)) {
39	                errors.add(field);
40	            }
41	        }
42	        validatePostcode(errors, request);
43	        if (!errors.isEmpty()) {
44	            throw new MissingOwnerFieldsException(errors);
45	        }
46	        normalizeEmail(request);
47	        validated.set(request);
48	    }
49	
50	    /**
51	     * Email is optional. When absent nothing is done; when present the schema {@code @Email}
52	     * constraint (checked above) has already rejected a syntactically invalid address with a
53	     * {@code 400}, so a value reaching here is valid and is stored and returned lower-cased.
54	     */
55	    private static void normalizeEmail(OwnerFieldsDto request) {
56	        String email = request.getEmail();
57	        if (email != null) {
58	            request.setEmail(email.toLowerCase(java.util.Locale.ROOT));
59	        }
60	    }
61	
62	    /**
63	     * Canonically normalize the address (trim, collapse whitespace, upper-case, expand common
64	     * abbreviations) and write it back onto the request so it is stored and returned in normalized
65	     * form. Running before the blank check means an address that is whitespace-only — and so blank
66	     * after normalization — is rejected as an {@code address} required-field error (400).
67	     */
68	    private static void normalizeAddress(OwnerFieldsDto request) {
69	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
70	    }
71	
72	    /**
73	     * Postcode is optional and validated only when present. Its 4-digit format is enforced by the
74	     * schema {@code @Pattern} (checked above, so a malformed value is already a {@code postcode}
75	     * error). When it is well-formed it must also be in range for the region derived from the
76	     * owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region
77	     * accepts any 4-digit postcode. An out-of-range postcode is a {@code postcode} error (400).
78	     */
79	    private static void validatePostcode(List<String> errors, OwnerFieldsDto request) {
80	        String postcode = request.getPostcode();
81	        if (postcode != null && !errors.contains("postcode")
82	                && !Postcodes.isValidForCity(postcode, request.getCity())) {
83	            errors.add("postcode");
84	        }
85	    }
86	
87	    private static void addIfBlank(List<String> errors, String name, String value) {
88	        if (value == null || value.isBlank()) {
89	            errors.add(name);
90	        }
91	    }
92	
93	    /**
94	     * Normalize the telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
95	     * '+' with country code is kept as-is; otherwise the number is assumed to be Australian ('+61')
96	     * and a single leading '0' is dropped from the national digits. The result must have 8 to 15
97	     * digits after the '+'. The E.164 value is written back onto the request so it is stored and
98	     * returned as {@code telephone}. Anything that cannot form a valid E.164 number is a
99	     * {@code telephone} error (400).
100	     */
101	    private static void normalizeTelephone(List<String> errors, OwnerFieldsDto request) {
102	        String e164 = toE164(request.getTelephone());
103	        if (e164 == null) {
104	            errors.add("telephone");
105	            return;
106	        }
107	        request.setTelephone(e164);
108	    }
109	
110	    /**
111	     * Country codes with a fixed national-number length. When a number's country code appears here
112	     * its national digits (everything after the code) must match exactly, otherwise it is rejected;
113	     * country codes not listed fall back to the generic 8–15 total-digit rule. '+61' (Australia)
114	     * requires 9 national digits, '+1' (NANP) requires 10.
115	     */
116	    private static final java.util.Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY =
117	            java.util.Map.of("61", 9, "1", 10);
118	
119	    /**
120	     * Convert a raw telephone into E.164 form, or return {@code null} when it cannot form a valid
121	     * E.164 number (fewer than 8 or more than 15 digits after the '+', a national-number length that
122	     * is wrong for its country code, or stray non-digit characters remaining after the allowed
123	     * separators are stripped).
124	     */
125	    static String toE164(String value) {
126	        if (value == null) {
127	            return null;
128	        }
129	        String cleaned = value.replaceAll("[\\s()-]", "");
130	        String digits;
131	        if (cleaned.startsWith("+")) {
132	            digits = cleaned.substring(1);
133	        }
134	        else {
135	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
136	            digits = "61" + national;
137	        }
138	        if (!digits.matches("[0-9]{8,15}")) {
139	            return null;
140	        }
141	        if (!hasValidNationalLength(digits)) {
142	            return null;
143	        }
144	        return "+" + digits;
145	    }
146	
147	    /**
148	     * For a country code with a fixed national-number length, check the national digits (everything
149	     * after the code) match that length exactly. Unknown country codes pass (already bounded by the
150	     * generic 8–15 total-digit rule).
151	     */
152	    private static boolean hasValidNationalLength(String digits) {
153	        for (java.util.Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
154	            String code = entry.getKey();
155	            if (digits.startsWith(code)) {
156	                return digits.length() - code.length() == entry.getValue();
157	            }
158	        }
159	        return true;
160	    }
161	}
