259	import net.officefloor.plugin.variable.Val;
260	import org.springframework.samples.petclinic.model.Owner;
261	import org.springframework.samples.petclinic.repository.OwnerRepository;
262	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
263	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
264	import org.springframework.samples.petclinic.rest.function.common.IdentityKeys;
265	
266	/**
267	 * The duplicate-detection step of {@code POST /api/owners}. Runs after {@link ValidateOwnerFields}
268	 * has normalized the telephone and email. It computes the request's deterministic
269	 * {@code householdId} from its last name and postcode (see {@link Households#householdId}) and
270	 * rejects the create with a 409 Conflict in two cases:
271	 *
272	 * <ul>
273	 * <li><b>Identity duplicate</b> — the request's whole {@code identityKey}
274	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) equals an existing
275	 * owner's. This always rejects, even when {@code sharesHousehold} is set.</li>
276	 * <li><b>Household duplicate</b> — an existing owner already occupies the same household (same
277	 * computed {@code householdId}, i.e. same last name and postcode). This rejects <em>unless</em> the
278	 * request opts in with {@code sharesHousehold: true}, in which case the owner is created as a
279	 * declared household member.</li>
280	 * </ul>
281	 *
282	 * <p>{@code sharesHousehold} therefore only bypasses the household-duplicate block; it never lets a
283	 * full identity duplicate through.
284	 */
285	public class RejectDuplicateIdentity {
286	
287	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
288	            throws DuplicateIdentityException {
289	        String householdId = Households.householdId(request.getLastName(), request.getPostcode());
290	        String identityKey = IdentityKeys.of(request.getTelephone(), request.getEmail(), householdId);
291	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
292	        for (Owner existing : ownerRepository.findAll()) {
293	            if (identityKey.equals(IdentityKeys.of(existing))) {
294	                throw new DuplicateIdentityException(identityKey);
295	            }
296	            if (!sharesHousehold && householdId.equals(householdIdOf(existing))) {
297	                throw new DuplicateIdentityException(householdId);
298	            }
299	        }
300	    }
301	
302	    /** The household an existing owner belongs to, computed from its last name and postcode. */
303	    private static String householdIdOf(Owner existing) {
304	        return Households.householdId(existing.getLastName(), existing.getPostcode());
305	    }
306	}
