519	/**
520	 * Step of {@code POST /api/owners} that counts how many existing owners already share this owner's
521	 * {@code firstName} and {@code lastName} — compared case-insensitively — and stores the total on the
522	 * owner as {@code namesakeCount}.
523	 *
524	 * <p>Runs after {@link BuildOwner} so the owner carries its names, and before {@link SaveOwner} so
525	 * the count reflects only owners that existed before this create: the new owner is not yet persisted
526	 * and so is never counted among its own namesakes. {@code @Val} yields the built owner, mutated in
527	 * place and persisted by the save step.
528	 */
529	public class AssignNamesakeCount {
530	
531	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
532	        String firstName = normalize(owner.getFirstName());
533	        String lastName = normalize(owner.getLastName());
534	        int count = 0;
535	        for (Owner existing : ownerRepository.findAll()) {
536	            if (firstName.equals(normalize(existing.getFirstName()))
537	                    && lastName.equals(normalize(existing.getLastName()))) {
538	                count++;
539	            }
540	        }
541	        owner.setNamesakeCount(count);
