587	package org.springframework.samples.petclinic.rest.function.owner;
588	
589	import net.officefloor.plugin.variable.Val;
590	import org.springframework.samples.petclinic.model.Owner;
591	import org.springframework.samples.petclinic.repository.OwnerRepository;
592	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
593	
594	/**
595	 * Soft-match step of {@code POST /api/owners}. By the time it runs the request has already passed
596	 * {@link RejectDuplicateIdentity}, so it is <em>not</em> a hard duplicate; this step then looks for a
597	 * weaker signal that it might be one anyway: an existing owner that shares this owner's
598	 * {@code lastName} (compared case-insensitively) and {@code postcode} but has a <em>different</em>
599	 * telephone. Such an owner is still created, but is flagged with {@code possibleDuplicate = true} and
600	 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest id when several match).
601	 * When nothing matches, {@code possibleDuplicate} is set to {@code false} and no id is recorded.
602	 *
603	 * <p>A <em>declared</em> household member — one created with {@code sharesHousehold: true} — is never
604	 * flagged: it already reached this step by opting past the household-duplicate block in
605	 * {@link RejectDuplicateIdentity}, so sharing a same-household owner's lastName and postcode is
606	 * expected, not a suspected duplicate.
607	 *
608	 * <p>Runs after {@link BuildOwner} so the owner carries its normalized lastName, postcode and
609	 * telephone, and before {@link SaveOwner} so the comparison sees only owners that existed before this
610	 * create — the new owner is not yet persisted and so never matches itself. {@code @Val} yields the
611	 * built owner, mutated in place and persisted by the save step.
612	 */
613	public class AssignPossibleDuplicate {
614	
615	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
616	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
617	            // A declared household member is not a suspected duplicate.
618	            owner.setPossibleDuplicate(false);
619	            owner.setPossibleDuplicateOf(null);
620	            return;
621	        }
622	        String lastName = Households.normalizeName(owner.getLastName());
623	        String postcode = normalizePostcode(owner.getPostcode());
624	        String telephone = owner.getTelephone();
625	        Integer match = null;
626	        if (postcode != null) {
627	            for (Owner existing : ownerRepository.findAll()) {
628	                if (lastName.equals(Households.normalizeName(existing.getLastName()))
629	                        && postcode.equals(normalizePostcode(existing.getPostcode()))
630	                        && !equalsSafely(telephone, existing.getTelephone())
631	                        && existing.getId() != null
632	                        && (match == null || existing.getId() < match)) {
633	                    match = existing.getId();
634	                }
635	            }
636	        }
637	        owner.setPossibleDuplicate(match != null);
638	        owner.setPossibleDuplicateOf(match);
639	    }
640	
641	    /** Trim the postcode, treating a null or blank value as absent (no possible-duplicate match). */
642	    private static String normalizePostcode(String value) {
643	        if (value == null) {
644	            return null;
645	        }
646	        String trimmed = value.trim();
647	        return trimmed.isEmpty() ? null : trimmed;
648	    }
649	
650	    private static boolean equalsSafely(String a, String b) {
651	        return a == null ? b == null : a.equals(b);
652	    }
653	}
